import os, glob, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    # Look for parent sessions directory
    parent_dir = os.path.dirname(os.path.dirname(d))
    sessions_file = None

    # Find jsonl files in parent directories
    for dirpath, dirnames, filenames in os.walk(parent_dir):
        if 'sessions' in dirpath:
            for f in filenames:
                if f.endswith('.jsonl'):
                    sessions_file = os.path.join(dirpath, f)
                    break
        if sessions_file:
            break

    if not sessions_file:
        sessions_file = f"{d}.jsonl"

    t = open(sessions_file).read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

