def generate_pattern(input_grid):
    """Generate output grid based on input '3' markers"""
    h, w = len(input_grid), len(input_grid[0])
    output = [[0]*w for _ in range(h)]

    # Find all positions with value 3
    threes = [(r,c) for r in range(h) for c in range(w) if input_grid[r][c] == 3]

    # For each 3, draw its local pattern
    for r_in, c_in in threes:
        # Keep the 3
        if 0 <= r_in < h and 0 <= c_in < w:
            output[r_in][c_in] = 3

        # Top bar of 5s at (r_in-2, c_in-2) to (r_in-2, c_in+2)
        if r_in-2 >= 0:
            for dc in [-2, -1, 0, 1, 2]:
                c = c_in + dc
                if 0 <= c < w:
                    output[r_in-2][c] = 5

        # Bottom bar of 8s at (r_in+2, c_in-2) to (r_in+2, c_in+2)
        if r_in+2 < h:
            for dc in [-2, -1, 0, 1, 2]:
                c = c_in + dc
                if 0 <= c < w:
                    # Will be overwritten by filler if outside main shape
                    pass

            # Filler 2s outside main shape horizontal extent on the same row
            for c in range(w):
                if c < c_in-2 or c > c_in+2:
                    output[r_in+2][c] = 2

        # Vertical bars of 2s at rows r_in-1 to r_in+1, cols c_in-2 and c_in+2
        for r_out in range(r_in-1, r_in+2):  # r-1, r, r+1
            for dc in [-2, 2]:
                c = c_in + dc
                if 0 <= r_out < h and 0 <= c < w:
                    output[r_out][c] = 2

    return output

